// API de equipos Pokemon.
//
// ====================================================================
//  VERSION 1.0 (ANTES) - contiene fallas de seguridad INTENCIONALES
//  usadas como objeto de las pruebas del Parcial 1, Actividad 2.
//  Cada bloque marcado con [VULN-n] se corrige en la version 1.1.
// ====================================================================
import express from "express";
import jwt from "jsonwebtoken";
import crypto from "node:crypto";

// [VULN-1] Secreto JWT embebido en el codigo fuente (CWE-798).
//          Deberia leerse de una variable de entorno.
const JWT_SECRET = "pokemon-super-secreto-123";

// [VULN-2] Contrasenas en texto plano. Esta funcion "hashea" sin hacer
//          nada real; se mantiene para que el cambio a la v1.1 sea claro.
function hashPassword(plain) {
  return plain; // CWE-256: almacenamiento de credenciales sin cifrar
}
function verifyPassword(plain, stored) {
  return plain === stored;
}

export function createApp(db) {
  const app = express();
  app.use(express.json());

  function auth(req, res, next) {
    const header = req.headers.authorization || "";
    const token = header.replace("Bearer ", "");
    try {
      req.user = jwt.verify(token, JWT_SECRET);
      next();
    } catch {
      res.status(401).json({ error: "Token invalido o ausente" });
    }
  }

  // --- Registro ----------------------------------------------------
  app.post("/api/register", (req, res) => {
    const { username, password } = req.body || {};
    if (!username || !password) {
      return res.status(400).json({ error: "username y password requeridos" });
    }
    try {
      const info = db
        .prepare("INSERT INTO users (username, password) VALUES (?, ?)")
        .run(username, hashPassword(password));
      res.status(201).json({ id: info.lastInsertRowid, username });
    } catch {
      res.status(409).json({ error: "El usuario ya existe" });
    }
  });

  // --- Inicio de sesion --------------------------------------------
  app.post("/api/login", (req, res) => {
    const { username, password } = req.body || {};
    const user = db
      .prepare("SELECT * FROM users WHERE username = ?")
      .get(username);
    if (!user || !verifyPassword(password, user.password)) {
      return res.status(401).json({ error: "Credenciales invalidas" });
    }
    const token = jwt.sign({ id: user.id, username: user.username }, JWT_SECRET);
    res.json({ token });
  });

  // --- Listar / buscar equipos del usuario -------------------------
  app.get("/api/teams", auth, (req, res) => {
    const { name } = req.query;
    // [VULN-3] Inyeccion SQL: el filtro `name` se concatena directamente
    //          en la consulta (CWE-89). Ademas no filtra por user_id,
    //          por lo que expone equipos de otros usuarios.
    let sql = "SELECT * FROM teams WHERE 1=1";
    if (name) {
      sql += " AND name LIKE '%" + name + "%'";
    }
    try {
      const rows = db.prepare(sql).all();
      res.json(rows.map(parseTeam));
    } catch (e) {
      // [VULN-4] Fuga de detalles internos en el mensaje de error (CWE-209).
      res.status(500).json({ error: e.message, sql });
    }
  });

  // --- Leer un equipo por id ---------------------------------------
  app.get("/api/teams/:id", auth, (req, res) => {
    // [VULN-5] IDOR / Broken Access Control (CWE-639): no verifica que el
    //          equipo pertenezca a req.user. Cualquier usuario autenticado
    //          puede leer el equipo de otro.
    const team = db
      .prepare("SELECT * FROM teams WHERE id = ?")
      .get(req.params.id);
    if (!team) return res.status(404).json({ error: "Equipo no encontrado" });
    res.json(parseTeam(team));
  });

  // --- Crear equipo ------------------------------------------------
  app.post("/api/teams", auth, (req, res) => {
    const { name, pokemon } = req.body || {};
    // [VULN-6] Falta de validacion de entradas (CWE-20): no valida el
    //          nombre, ni que `pokemon` sea una lista de <=6 ids validos.
    const info = db
      .prepare("INSERT INTO teams (user_id, name, pokemon) VALUES (?, ?, ?)")
      .run(req.user.id, name, JSON.stringify(pokemon));
    res.status(201).json({ id: info.lastInsertRowid, name, pokemon });
  });

  // --- Borrar equipo -----------------------------------------------
  app.delete("/api/teams/:id", auth, (req, res) => {
    // [VULN-5] Mismo IDOR: borra por id sin comprobar el dueno.
    const info = db
      .prepare("DELETE FROM teams WHERE id = ?")
      .run(req.params.id);
    if (info.changes === 0) {
      return res.status(404).json({ error: "Equipo no encontrado" });
    }
    res.json({ deleted: Number(req.params.id) });
  });

  app.get("/api/health", (_req, res) => res.json({ status: "ok" }));
  return app;
}

function parseTeam(row) {
  return {
    id: row.id,
    user_id: row.user_id,
    name: row.name,
    pokemon: safeParse(row.pokemon),
  };
}
function safeParse(s) {
  try {
    return JSON.parse(s);
  } catch {
    return s;
  }
}

export const _internal = { hashPassword, verifyPassword, JWT_SECRET };

// Carga datos sinteticos reproducibles en la base.
// Uso: node src/seed.js [ruta.db]
import { createDb } from "./db.js";
import { createApp, _internal } from "./app.js";

export function seed(db) {
  const insUser = db.prepare(
    "INSERT INTO users (username, password) VALUES (?, ?)"
  );
  const insTeam = db.prepare(
    "INSERT INTO teams (user_id, name, pokemon) VALUES (?, ?, ?)"
  );

  // Contrasenas de laboratorio, no reales.
  const users = [
    { u: "ash", p: "pikachu123" },
    { u: "misty", p: "staryu456" },
    { u: "brock", p: "onix789" },
  ];
  const ids = {};
  for (const { u, p } of users) {
    const info = insUser.run(u, _internal.hashPassword(p));
    ids[u] = info.lastInsertRowid;
  }

  insTeam.run(ids.ash, "Kanto Starters", JSON.stringify([1, 4, 7]));
  insTeam.run(ids.misty, "Agua total", JSON.stringify([7, 54, 120, 121]));
  insTeam.run(ids.brock, "Roca dura", JSON.stringify([74, 95]));
  return ids;
}

// Ejecucion directa desde CLI.
if (import.meta.url === `file://${process.argv[1]}`) {
  const path = process.argv[2] || "poke.db";
  const db = createDb(path);
  db.exec("DELETE FROM teams; DELETE FROM users;");
  seed(db);
  createApp(db); // valida que la app carga sin errores
  console.log(`Base sembrada en ${path}: usuarios ash, misty, brock`);
}

// Pruebas automatizadas de seguridad sobre la API de equipos.
// Se ejecutan contra la app real (supertest) con la base sembrada.
// Los mismos casos corren sin cambios en la v1.0 (antes) y v1.1 (despues):
// en "antes" varios fallan (revelan la vulnerabilidad); en "despues" pasan.
import { jest } from "@jest/globals";
import request from "supertest";
import { createDb } from "../src/db.js";
import { createApp } from "../src/app.js";
import { seed } from "../src/seed.js";

let app;

beforeEach(() => {
  const db = createDb(":memory:");
  seed(db);
  app = createApp(db);
});

async function login(username, password) {
  const res = await request(app)
    .post("/api/login")
    .send({ username, password });
  return res.body.token;
}

describe("Autenticacion (control base)", () => {
  // CP-07
  test("CP-07 rechaza acceso sin token (401)", async () => {
    const res = await request(app).get("/api/teams/1");
    expect(res.status).toBe(401);
  });
});

describe("Acceso entre usuarios (IDOR / Broken Access Control)", () => {
  // CP-01
  test("CP-01 un usuario NO puede leer el equipo de otro", async () => {
    const tokenAsh = await login("ash", "pikachu123");
    // El equipo 2 pertenece a misty, no a ash.
    const res = await request(app)
      .get("/api/teams/2")
      .set("Authorization", `Bearer ${tokenAsh}`);
    expect(res.status).toBe(403);
  });

  // CP-02
  test("CP-02 un usuario NO puede borrar el equipo de otro", async () => {
    const tokenAsh = await login("ash", "pikachu123");
    const res = await request(app)
      .delete("/api/teams/2")
      .set("Authorization", `Bearer ${tokenAsh}`);
    expect(res.status).toBe(403);
  });

  test("CP-01b un usuario SI puede leer su propio equipo (200)", async () => {
    const tokenAsh = await login("ash", "pikachu123");
    const res = await request(app)
      .get("/api/teams/1")
      .set("Authorization", `Bearer ${tokenAsh}`);
    expect(res.status).toBe(200);
    expect(res.body.name).toBe("Kanto Starters");
  });
});

describe("Inyeccion SQL", () => {
  // CP-03
  test("CP-03 el filtro name no permite inyeccion booleana", async () => {
    const token = await login("ash", "pikachu123");
    const res = await request(app)
      .get("/api/teams")
      .query({ name: "' OR '1'='1" })
      .set("Authorization", `Bearer ${token}`);
    // No debe devolver equipos de otros usuarios ni volcar toda la tabla.
    expect(res.status).toBeLessThan(500);
    const ajenos = (res.body || []).filter((t) => t.user_id !== 1);
    expect(ajenos).toHaveLength(0);
  });
});

describe("Validacion de entradas", () => {
  async function crear(token, body) {
    return request(app)
      .post("/api/teams")
      .set("Authorization", `Bearer ${token}`)
      .send(body);
  }

  // CP-04
  test("CP-04 rechaza id de pokemon fuera de rango", async () => {
    const token = await login("ash", "pikachu123");
    const res = await crear(token, { name: "Prueba", pokemon: [-5, 99999] });
    expect(res.status).toBe(400);
  });

  // CP-05
  test("CP-05 rechaza equipos con mas de 6 pokemon", async () => {
    const token = await login("ash", "pikachu123");
    const res = await crear(token, {
      name: "Demasiados",
      pokemon: [1, 2, 3, 4, 5, 6, 7],
    });
    expect(res.status).toBe(400);
  });

  // CP-06
  test("CP-06 rechaza nombre con contenido tipo script (XSS almacenado)", async () => {
    const token = await login("ash", "pikachu123");
    const res = await crear(token, {
      name: "<script>alert(1)</script>",
      pokemon: [1],
    });
    expect(res.status).toBe(400);
  });
});
